async function savePreset(name){const o=active();if(!o)throw Error('Selecione um objeto.');name=String(name||'').trim().slice(0,80);if(!name)throw Error('Informe um nome.');syncRuntimeParams(o);const params=migrateParams(structuredClone(o.params));const row={id:uid(),name,params,version:2,featureType:'cookie-cutter'};await persistPresets([...presetRows,row]);$('savedPreset').value=row.id;return row;}
