  function renderHatchGallery(){const host=$('hatchGallery');if(!host)return;const current=$('pres-hatchType').value||hatchProfile().type||'parallel';if(host.dataset.current===current&&host.children.length)return;host.dataset.current=current;host.innerHTML='';for(const [value,label] of hatchTypes.filter(([v])=>v!=='none')){const btn=document.createElement('button');btn.type='button';btn.className='hatch-thumb'+(current===value?' active':'');btn.innerHTML=`<canvas aria-hidden="true"></canvas><div class="cap">${label}</div>`;drawHatchThumb(btn.querySelector('canvas'),value);btn.onclick=()=>{activateHatchTargets();$('pres-hatchType').value=value;forEachHatchTarget((hp)=>hp.type=value);syncHatchControls();refreshAppearance();autosave();};host.appendChild(btn);}}
